after.content:
:8080 {
  encode zstd gzip
  @relay path /api/* /metrics
  reverse_proxy @relay relay:18090
  @relayws path /relay/v1
  reverse_proxy @relayws relay:18091
  reverse_proxy web:8080
  header {
    X-Content-Type-Options nosniff
    Referrer-Policy no-referrer
    Permissions-Policy "camera=(), microphone=(), geolocation=()"
    Content-Security-Policy "default-src 'self'; connect-src 'self' wss:; img-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'"
  }
}
